const API='/api';
let token=localStorage.getItem('mp_token');
let me=JSON.parse(localStorage.getItem('mp_user')||'null');
let cart=JSON.parse(localStorage.getItem('mp_cart')||'[]');
let riderWatch=null, chatTimer=null, trackTimer=null;
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=v=>`৳${Number(v||0).toFixed(0)}`;
function askDialog({title='Confirm',message='',input=false,placeholder='',confirmText='Confirm',danger=false,defaultValue=''}){return new Promise(res=>{const d=document.createElement('div');d.className='dialog';d.innerHTML=`<div class="dialog-box" role="dialog" aria-modal="true"><h3>${esc(title)}</h3>${message?`<p>${esc(message)}</p>`:''}${input?`<textarea id="dlgInput" class="field" rows="3" placeholder="${esc(placeholder)}">${esc(defaultValue)}</textarea>`:''}<div class="dialog-actions"><button class="btn" data-r="0">Cancel</button><button class="btn ${danger?'danger-solid':'primary'}" data-r="1">${esc(confirmText)}</button></div></div>`;const onKey=e=>{if(e.key==='Escape')done(null)};const done=v=>{d.remove();document.removeEventListener('keydown',onKey);res(v)};d.addEventListener('click',e=>{if(e.target===d)return done(null);const b=e.target.closest('button[data-r]');if(!b)return;if(b.dataset.r==='1')done(input?(d.querySelector('#dlgInput').value.trim()||defaultValue):true);else done(input?null:false)});document.addEventListener('keydown',onKey);document.body.appendChild(d);(d.querySelector('#dlgInput')||d.querySelector('button[data-r="1"]')).focus()})}
function askConfirm(message,opt={}){return askDialog({title:opt.title||'Are you sure?',message,confirmText:opt.confirmText||'Confirm',danger:!!opt.danger}).then(v=>v===true)}
function askText(title,opt={}){return askDialog({title,input:true,placeholder:opt.placeholder||'',confirmText:opt.confirmText||'Submit',danger:!!opt.danger,defaultValue:opt.defaultValue||''})}
function pwField(id,label,ph,ac,enter){return `<label class="label" for="${id}">${label}</label><div class="pw-wrap"><input id="${id}" class="field" type="password" placeholder="${ph}" autocomplete="${ac||'current-password'}"${enter?` onkeydown="if(event.key==='Enter')${enter}"`:''}><button type="button" class="pw-toggle" onclick="togglePw('${id}',this)" aria-label="Show or hide password">Show</button></div>`}
function togglePw(id,b){const i=$(id);if(!i)return;const show=i.type==='password';i.type=show?'text':'password';b.textContent=show?'Hide':'Show'}
function setBusy(btn,busy,text){if(!btn)return;if(busy){btn.dataset.t=btn.textContent;btn.disabled=true;btn.textContent=text||'Please wait…'}else{btn.disabled=false;btn.textContent=btn.dataset.t||btn.textContent}}
function saveCart(){localStorage.setItem('mp_cart',JSON.stringify(cart));}
function toast(t){const e=$('toast');if(!e)return;e.textContent=t;e.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>e.classList.remove('show'),2800)}
function closeModal(){clearInterval(window._otpTimer);clearInterval(chatTimer);clearInterval(trackTimer);$('modal')?.classList.remove('show')}
function openModal(html){$('modalContent').innerHTML=html;$('modal').classList.add('show')}
function logout(){if(riderWatch!==null&&navigator.geolocation)navigator.geolocation.clearWatch(riderWatch);riderWatch=null;token=null;me=null;localStorage.removeItem('mp_token');localStorage.removeItem('mp_user');location.href='/';}
async function api(path,opt={}){const h={...(opt.headers||{})};if(opt.body&&typeof opt.body!=='string' && !(opt.body instanceof FormData)){h['Content-Type']='application/json';opt.body=JSON.stringify(opt.body)}if(token)h.Authorization='Bearer '+token;const r=await fetch(API+path,{...opt,headers:h});let d=null;try{d=await r.json()}catch{}if(!r.ok){throw new Error(d?.message||d?.detail||d?.error||`Request failed (${r.status})`)}return d}
async function uploadOptionalImage(inputId,folder,fallbackUrl){const file=$(inputId)?.files?.[0];if(!file)return fallbackUrl||'';const form=new FormData();form.append('file',file);const result=await api('/uploads?folder='+encodeURIComponent(folder),{method:'POST',body:form});if(!result?.url)throw Error('Image upload did not return a URL');return result.url}
function showDashboardError(error){const message=error?.message||'Unable to load dashboard.';$('app').innerHTML=nav()+`<main class="section"><div class="panel"><span class="eyebrow">DASHBOARD ACCESS</span><h2>We couldn't open this dashboard</h2><p>${esc(message)}</p><p class="muted">Check that you are signed in with the correct role, that your account is approved, and that the backend/database are running.</p><button class="btn primary" onclick="dashboard()">Try again</button> <button class="btn" onclick="logout()">Sign in again</button></div></main>`}
function mapsLink(lat,lng){return `https://www.openstreetmap.org/?mlat=${encodeURIComponent(lat)}&mlon=${encodeURIComponent(lng)}#map=16/${encodeURIComponent(lat)}/${encodeURIComponent(lng)}`}
function mapEmbed(lat,lng){const padLng=.008,padLat=.006;const bbox=[lng-padLng,lat-padLat,lng+padLng,lat+padLat].map(v=>Number(v).toFixed(6)).join('%2C');return `https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&layer=mapnik&marker=${encodeURIComponent(lat)}%2C${encodeURIComponent(lng)}`}
async function reverseGeo(lat,lng){try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lng)}&zoom=18&addressdetails=1`,{headers:{'Accept-Language':'en'}});if(!r.ok)throw 0;const d=await r.json();return {display:d.display_name||`${lat.toFixed(6)}, ${lng.toFixed(6)}`,short:[d.address?.road,d.address?.suburb||d.address?.neighbourhood,d.address?.city||d.address?.town,d.address?.state].filter(Boolean).join(', ')};}catch{return {display:`${lat.toFixed(6)}, ${lng.toFixed(6)}`,short:'GPS coordinates'}}}
function gpsError(e){if(e?.code===1)return'Location permission was denied. Allow Location for this site and try again.';if(e?.code===2)return'Your device could not determine a location. Turn on GPS/Wi-Fi and try again.';if(e?.code===3)return'Location detection timed out. Try again outdoors or near a window.';return'Location could not be detected. Please try again.'}
function position(){return new Promise((res,rej)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(res,rej,{enableHighAccuracy:true,timeout:20000,maximumAge:0}):rej(new Error('Geolocation is not supported by this browser.')))}
function setSession(r){token=r.token;me={id:r.id,name:r.name,email:r.email||r.phone,phone:r.phone,role:r.role,verificationStatus:r.verificationStatus};localStorage.setItem('mp_token',token);setTimeout(()=>window.enablePush&&enablePush(),1500);localStorage.setItem('mp_user',JSON.stringify(me))}
function nav(){return `<header class="topbar"><a class="brand" href="/"><span class="logo"><i class="ic ic-plus"></i></span>Medi<em>Panda</em></a><nav><a href="/#pharmacies">Pharmacies</a><a href="/#medicines">Medicines</a><a href="/#how">How it works</a></nav><div class="nav-actions">${me?`<button class="btn ghost" onclick="dashboard()">${esc(me.name)} · ${esc(me.role)}</button><button class="btn" onclick="logout()">Logout</button>`:`<button class="btn" onclick="showLogin()">Login</button><button class="btn primary" onclick="showRegister()">Get started</button>`}<button class="cart-btn" onclick="openCart()"><i class="ic ic-cart"></i> <b>${cart.reduce((a,x)=>a+(x.qty||1),0)}</b></button></div></header>`}
async function home(){const site=await api('/site').catch(()=>({siteName:'MediPanda',heroTitle:'Medicines from trusted pharmacies, delivered to you.',heroText:'Browse verified pharmacies, find your medicines and track every delivery from pickup to doorstep.',heroVideoUrl:'https://cdn.pixabay.com/video/2025/07/06/289881_large.mp4',footerText:'Professional medicine delivery for everyday healthcare.'}));document.title=(site.siteName||'MediPanda')+' | Medicine delivered';$('app').innerHTML=nav()+`<main><section class="hero"><video autoplay muted loop playsinline class="hero-video"><source src="${esc(site.heroVideoUrl||'https://cdn.pixabay.com/video/2025/07/06/289881_large.mp4')}" type="video/mp4"></video><div class="hero-shade"></div><div class="hero-copy"><span class="eyebrow light">HEALTHCARE, DELIVERED BETTER</span><h1>${esc(site.heroTitle||'Medicines from trusted pharmacies, delivered to you.')}</h1><p>${esc(site.heroText||'Browse verified pharmacies, find your medicines and track every delivery from pickup to doorstep.')}</p><div class="hero-search"><span><i class="ic ic-search"></i></span><input id="homeSearch" placeholder="Search medicine, brand or pharmacy" onkeydown="if(event.key==='Enter')searchHome()"><button onclick="searchHome()">Search</button></div><div class="trust"><span><i class="ic ic-check"></i> Verified partners</span><span><i class="ic ic-check"></i> Live rider tracking</span><span><i class="ic ic-check"></i> Secure ordering</span></div></div><div class="hero-card"><strong>Fast local delivery</strong><span>From pharmacy to your door</span><b>24/7 order tracking</b></div></section><section class="benefits"><div><i class="ic ic-pill"></i> <b>10,000+ essentials</b><small>Everyday healthcare</small></div><div><i class="ic ic-clinic"></i> <b>Verified pharmacies</b><small>Trusted local partners</small></div><div><i class="ic ic-bike"></i> <b>Live delivery</b><small>Track your rider</small></div><div><i class="ic ic-chat"></i> <b>Order chat</b><small>Talk to your delivery team</small></div></section><section class="section" id="pharmacies"><div class="section-title"><div><span class="eyebrow">DISCOVER</span><h2>Popular pharmacies</h2><p>Choose a pharmacy and explore its complete medicine catalogue.</p></div></div><div id="pharmacyGrid" class="pharmacy-grid"></div></section><section class="section tinted" id="medicines"><div class="section-title"><div><span class="eyebrow">SHOP MEDICINES</span><h2>Popular healthcare essentials</h2><p>Browse by category or open a pharmacy for its full catalogue.</p></div></div><div class="chips"><button onclick="loadHomeMeds()">All</button><button onclick="loadHomeMeds('Fever & Pain')">Fever & Pain</button><button onclick="loadHomeMeds('Gastric')">Gastric</button><button onclick="loadHomeMeds('Vitamins')">Vitamins</button><button onclick="loadHomeMeds('First Aid')">First Aid</button><button onclick="loadHomeMeds('Allergy & Cold')">Allergy & Cold</button></div><div id="medicineGrid" class="medicine-grid"></div></section><section class="feature-video"><div><span class="eyebrow light">THE MEDIPANDA EXPERIENCE</span><h2>Order confidently.<br><em>Track everything.</em></h2><p>Pharmacy confirmation, rider assignment, live location and direct chat — all in one clean experience.</p></div><div class="feature-video-card"><video autoplay muted loop playsinline><source src="${esc(site.heroVideoUrl||'https://cdn.pixabay.com/video/2025/07/06/289881_large.mp4')}" type="video/mp4"></video><div><b>Order → Prepare → Deliver</b><span>Stay informed at every step</span></div></div></section><section class="section" id="how"><div class="section-title center"><span class="eyebrow">HOW IT WORKS</span><h2>Healthcare in three steps</h2></div><div class="steps"><article><b>01</b><span><i class="ic ic-search"></i></span><h3>Find your pharmacy</h3><p>Open a pharmacy and see its full medicine catalogue.</p></article><article><b>02</b><span><i class="ic ic-cart"></i></span><h3>Order securely</h3><p>Add medicines, share your delivery location and checkout.</p></article><article><b>03</b><span><i class="ic ic-bike"></i></span><h3>Track delivery</h3><p>A rider accepts your order and you can chat and track live.</p></article></div></section></main><footer class="footer"><div class="brand"><span class="logo"><i class="ic ic-plus"></i></span>Medi<em>Panda</em></div><p>${esc(site.footerText||'Professional medicine delivery for everyday healthcare.')}</p><span>© 2026 ${esc(site.siteName||'MediPanda')}</span></footer>`;await loadPharmacies();await loadHomeMeds();}
async function loadPharmacies(){try{const ps=await api('/pharmacies');$('pharmacyGrid').innerHTML=ps.map(p=>`<article class="pharmacy-card"><div class="pharmacy-image"><img src="${esc(p.image)}" alt="${esc(p.name)}"><span class="open-pill">${p.open?'● Open':'Closed'}</span></div><div class="pharmacy-info"><div class="rating">★ ${esc(p.rating)} <span>· ${esc(p.deliveryTime)}</span></div><h3>${esc(p.name)}</h3><p><i class="ic ic-pin"></i> ${esc([p.street,p.area,p.locationAddress].filter(Boolean).join(', ')||'Dhaka')}</p><p class="muted">${esc(p.description||'Verified pharmacy and healthcare partner.')}</p><button class="btn primary wide" onclick="openPharmacy('${p.id}')">Explore pharmacy →</button></div></article>`).join('')||'<div class="empty">No pharmacies available.</div>'}catch(e){toast(e.message)}}
async function loadHomeMeds(category){try{let u='/medicines';if(category)u+='?category='+encodeURIComponent(category);const ms=await api(u);$('medicineGrid').innerHTML=ms.slice(0,12).map(m=>medCard(m)).join('')||'<div class="empty">No medicines found.</div>'}catch(e){toast(e.message)}}
function medCard(m){return `<article class="medicine-card"><div class="med-img"><img src="${esc(m.image)}" alt="${esc(m.name)}"><span>${esc(m.category)}</span></div><div class="med-info"><small>${esc(m.manufacturer||'Verified supplier')}</small><h3>${esc(m.name)}</h3><p>${esc(m.genericName||'Healthcare essential')}</p><div class="med-bottom"><strong>${money(m.price)}</strong><button class="add-btn" onclick="addCart('${m.id}')"><i class="ic ic-plus"></i></button></div>${m.prescriptionRequired?'<div class="rx">Prescription required</div>':''}</div></article>`}
async function openPharmacy(id){location.href=`/pharmacy.html?id=${encodeURIComponent(id)}`}
async function renderPharmacyPage(){const id=new URLSearchParams(location.search).get('id');if(!id){location.href='/';return}try{const [p,ms]=await Promise.all([api('/pharmacies/'+id),api('/medicines?pharmacyId='+encodeURIComponent(id))]);document.title=`${p.name} | MediPanda`;$('app').innerHTML=nav()+`<main class="pharmacy-page"><section class="pharmacy-hero"><div><span class="eyebrow">VERIFIED PHARMACY</span><h1>${esc(p.name)}</h1><p>${esc(p.description||'Trusted medicines and healthcare essentials.')}</p><div class="ph-meta"><span>★ ${esc(p.rating)}</span><span><i class="ic ic-clock"></i> ${esc(p.deliveryTime)}</span><span><i class="ic ic-pin"></i> ${esc([p.street,p.area,p.locationAddress].filter(Boolean).join(', '))}</span></div><a class="btn light-btn" target="_blank" href="${mapsLink(p.latitude,p.longitude)}">Open location <i class="ic ic-external"></i></a></div><img src="${esc(p.image)}" alt="${esc(p.name)}"></section><section class="section"><div class="catalog-head"><div><span class="eyebrow">FULL CATALOGUE</span><h2>Medicines available here</h2><p>${ms.length} medicines · Search, filter and add directly to cart.</p></div><input id="catalogSearch" class="field search-field" placeholder="Search this pharmacy…" oninput="filterCatalog()"></div><div class="chips" id="catChips"><button onclick="filterCatalog('')">All</button>${[...new Set(ms.map(x=>x.category))].map(c=>`<button onclick="filterCatalog('${esc(c)}')">${esc(c)}</button>`).join('')}</div><div id="catalog" class="medicine-grid">${ms.map(m=>medCard(m)).join('')}</div></section></main>`;window.catalog=ms}catch(e){toast(e.message)}}
function filterCatalog(category){const q=($('catalogSearch')?.value||'').toLowerCase();const ms=(window.catalog||[]).filter(m=>(!category||m.category===category)&&(!q||`${m.name} ${m.genericName} ${m.manufacturer}`.toLowerCase().includes(q)));$('catalog').innerHTML=ms.map(m=>medCard(m)).join('')||'<div class="empty">No medicine matches your search.</div>'}
async function addCart(id){try{const m=await api('/medicines/'+id);if(cart.length&&cart[0].pharmacyId!==m.pharmacyId){if(!(await askConfirm('Your cart contains medicines from another pharmacy. Clear the cart and add this item?',{title:'Start a new cart?',confirmText:'Clear & add'})))return;cart=[]}const x=cart.find(i=>i.id===m.id);if(x)x.qty=(x.qty||1)+1;else cart.push({...m,qty:1});saveCart();toast(`${m.name} added to cart`);renderCurrent()}catch(e){toast(e.message)}}
function cartTotal(){return cart.reduce((s,x)=>s+(Number(x.price)||0)*(x.qty||1),0)}
function openCart(){openModal(`<div class="modal-head"><span class="eyebrow">YOUR CART</span><h2>Ready to checkout?</h2></div><div class="cart-list">${cart.length?cart.map(x=>`<div class="cart-row"><img src="${esc(x.image)}"><div><b>${esc(x.name)}</b><small>${money(x.price)} × ${x.qty}</small></div><div class="qty"><button onclick="changeQty('${x.id}',-1)">−</button><b>${x.qty}</b><button onclick="changeQty('${x.id}',1)">+</button></div><strong>${money(x.price*x.qty)}</strong></div>`).join(''):'<div class="empty">Your cart is empty.</div>'}</div>${cart.length?`<div class="cart-total"><span>Subtotal</span><b>${money(cartTotal())}</b></div><button class="btn primary wide" onclick="checkout()">Checkout · ${money(cartTotal()+50)}</button>`:''}`)}
function changeQty(id,d){const x=cart.find(i=>i.id===id);if(!x)return;x.qty+=d;if(x.qty<=0)cart=cart.filter(i=>i.id!==id);saveCart();openCart()}
function showLogin(msg=''){openModal(`<div class="auth-head"><span class="eyebrow">WELCOME BACK</span><h2>Sign in to MediPanda</h2><p class="muted">Order medicines, track deliveries and manage your workspace.</p></div>${msg?`<p class="notice success">${esc(msg)}</p>`:''}<div id="googleSignIn" class="top-gap"></div><div class="divider"><span>or continue with email / phone</span></div><label class="label" for="loginId">Phone or Gmail / Email</label><input id="loginId" class="field" autocomplete="username" placeholder="017xxxxxxxx or you@gmail.com" onkeydown="if(event.key==='Enter')$('loginPass').focus()">${pwField('loginPass','Password','Enter your password','current-password','login()')}<div class="row-between"><span></span><a class="link" onclick="showForgotPassword($('loginId').value)">Forgot password?</a></div><button id="loginBtn" class="btn primary wide top-gap" onclick="login()">Sign in</button><p class="muted center">New to MediPanda? <a onclick="showRegister()">Create an account</a></p>`);setupGoogleSignIn();setTimeout(()=>$('loginId')?.focus(),50)}
function showForgotPassword(prefill=''){const pre=/@/.test(prefill||'')?prefill:'';openModal(`<div class="auth-head"><span class="eyebrow">ACCOUNT RECOVERY</span><h2>Forgot your password?</h2><p class="muted">Enter the Gmail address you registered with. We’ll email you a 6-digit code to reset your password.</p></div><label class="label" for="resetEmail">Gmail / Email</label><input id="resetEmail" class="field" type="email" autocomplete="email" placeholder="you@gmail.com" value="${esc(pre)}" onkeydown="if(event.key==='Enter')sendPasswordResetOtp()"><button id="resetSendBtn" class="btn primary wide top-gap" onclick="sendPasswordResetOtp()">Send reset code</button><p class="muted center"><a onclick="showLogin()">← Back to sign in</a></p>`);setTimeout(()=>$('resetEmail')?.focus(),50)}
async function sendPasswordResetOtp(isResend){const email=(isResend?window._resetEmail:$('resetEmail')?.value||'').trim().toLowerCase();if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){toast('Enter a valid email address');return}const btn=isResend?$('resendBtn'):$('resetSendBtn');setBusy(btn,true,'Sending…');try{await api('/auth/forgot-password',{method:'POST',body:{email}});window._resetEmail=email;if(!isResend)showResetStep(email);else{startResendTimer();toast('A new code has been sent')}}catch(e){setBusy(btn,false);toast(e.message)}}
function showResetStep(email){openModal(`<div class="auth-head"><span class="eyebrow">CHECK YOUR INBOX</span><h2>Set a new password</h2><p class="muted">If <b>${esc(email)}</b> is registered, a 6-digit code was sent. It expires in 10 minutes.</p></div><label class="label" for="resetCode">6-digit code</label><input id="resetCode" class="field otp-input" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="••••••" oninput="this.value=this.value.replace(/\D/g,'')">${pwField('resetNewPassword','New password','At least 8 characters','new-password')}${pwField('resetConfirmPassword','Confirm new password','Repeat new password','new-password','submitPasswordReset()')}<button id="resetSubmitBtn" class="btn primary wide top-gap" onclick="submitPasswordReset()">Reset password</button><div class="row-between top-gap"><a class="link" onclick="showForgotPassword('${esc(email)}')">Use a different email</a><button id="resendBtn" class="link-btn" onclick="sendPasswordResetOtp(true)" disabled>Resend code</button></div>`);startResendTimer();setTimeout(()=>$('resetCode')?.focus(),50)}
function startResendTimer(){clearInterval(window._otpTimer);let left=60;const tick=()=>{const b=$('resendBtn');if(!b){clearInterval(window._otpTimer);return}if(left>0){b.disabled=true;b.textContent=`Resend code in ${left}s`;left--}else{clearInterval(window._otpTimer);b.disabled=false;b.textContent='Resend code'}};tick();window._otpTimer=setInterval(tick,1000)}
async function submitPasswordReset(){const email=window._resetEmail,code=$('resetCode').value.trim(),password=$('resetNewPassword').value,confirm=$('resetConfirmPassword').value;if(!/^\d{6}$/.test(code)){toast('Enter the 6-digit code from your email');return}if(password.length<8){toast('Password must be at least 8 characters');return}if(password!==confirm){toast('Passwords do not match');return}const btn=$('resetSubmitBtn');setBusy(btn,true,'Resetting…');try{await api('/auth/reset-password',{method:'POST',body:{email,code,newPassword:password}});clearInterval(window._otpTimer);showLogin('Password reset successfully. Sign in with your new password.')}catch(e){setBusy(btn,false);toast(e.message)}}
async function login(){const lb=$('loginBtn');setBusy(lb,true,'Signing in…');try{const r=await api('/auth/login',{method:'POST',body:{identifier:$('loginId').value,password:$('loginPass').value}});setSession(r);closeModal();toast('Welcome back');dashboard()}catch(e){setBusy(lb,false);toast(e.message)}}
function showRegister(){openModal(`<span class="eyebrow">JOIN MEDIPANDA</span><h2>Create your account</h2><div id="googleSignIn" class="top-gap"></div><div class="muted center">or register with email</div><div class="role-tabs"><button class="active" id="roleCustomer" onclick="selectRole('CUSTOMER')">Customer</button><button id="rolePharmacy" onclick="selectRole('PHARMACY')">Pharmacy</button><button id="roleRider" onclick="selectRole('RIDER')">Rider</button></div><div id="regForm"></div>`);setupGoogleSignIn();selectRole('CUSTOMER')}
function selectRole(role){window.regRole=role;document.querySelectorAll('.role-tabs button').forEach(b=>b.classList.remove('active'));$('role'+role.charAt(0)+role.slice(1).toLowerCase())?.classList.add('active');$('regForm').innerHTML=`<label class="label">Full name</label><input id="regName" class="field" placeholder="Your full name" required>${role==='PHARMACY'?'<label class="label">Pharmacy / business name</label><input id="regBusiness" class="field" placeholder="e.g. MediCare Pharmacy"><div class="two"><div><label class="label">Area / City</label><input id="regArea" class="field" placeholder="Dhanmondi"></div><div><label class="label">Street / Road</label><input id="regStreet" class="field" placeholder="Road 7, House 12"></div></div>':''}<label class="label">Phone number</label><input id="regPhone" class="field" placeholder="017xxxxxxxx"><label class="label">Gmail <span class="required">*</span></label><input id="regEmail" class="field" type="email" placeholder="you@gmail.com" required>${pwField('regPass','Password','Minimum 8 characters','new-password')}${role==='RIDER'?'<label class="label">Vehicle</label><select id="regVehicle" class="field"><option>Bike</option><option>Cycle</option><option>Motorbike</option></select>':''}${role!=='CUSTOMER'?`<div class="verification-upload"><b>${role==='RIDER'?'Rider verification':'Pharmacy verification'}</b><p>Upload a clear <strong>${role==='RIDER'?'NID':'Trade Licence'}</strong> image or PDF. Admin will review it before activation.</p><input id="regDoc" type="file" accept="image/*,.pdf"><small>Image: up to 900 KB · PDF: up to 1 MB</small></div>`:''}<button id="registerBtn" class="btn primary wide top-gap" onclick="registerAccount()">${role==='CUSTOMER'?'Create customer account':'Submit for admin approval'}</button>`}
async function registerAccount(){const btn=$('registerBtn');try{const role=window.regRole,name=$('regName').value.trim(),phone=$('regPhone').value.trim(),email=$('regEmail').value.trim(),pass=$('regPass').value;if(!name||!pass)throw Error('Name and password are required');if(!email)throw Error('Gmail is required for registration');if(!/^[A-Za-z0-9._%+-]+@gmail\.com$/i.test(email))throw Error('Please use a valid Gmail address');if(pass.length<8)throw Error("Password must be at least 8 characters");const doc=$('regDoc')?.files?.[0];if(role!=='CUSTOMER'&&!doc)throw Error(`Please upload your ${role==='RIDER'?'NID':'Trade Licence'} document`);if(doc){if(doc.type==='application/pdf'&&doc.size>2*1024*1024)throw Error('PDF must be 2 MB or smaller');if(doc.type!=='application/pdf'&&(!doc.type.startsWith('image/')||doc.size>2*1024*1024))throw Error('Image must be 2 MB or smaller');}btn.disabled=true;btn.textContent='Submitting…';const form=new FormData();[['name',name],['email',email],['phone',phone],['password',pass],['role',role],['businessName',$('regBusiness')?.value||''],['area',$('regArea')?.value||''],['street',$('regStreet')?.value||''],['vehicle',$('regVehicle')?.value||'']].forEach(([k,v])=>form.append(k,v));if(doc)form.append('verificationDocument',doc);const r=await api('/auth/register',{method:'POST',body:form});if(email){showOtpVerification(email,pass,role,name);return}if(role==='CUSTOMER'){if(!r.token)throw Error('Customer account could not be created');setSession(r);closeModal();toast('Account created');dashboard()}else{closeModal();openModal(`<div class="success-panel"><div class="success-icon"><i class="ic ic-check"></i></div><span class="eyebrow">APPLICATION RECEIVED</span><h2>Thanks, ${esc(name)}.</h2><p>Your ${role.toLowerCase()} application has been submitted successfully. An admin will review your document before you can sign in.</p><button class="btn primary wide" onclick="closeModal()">Done</button></div>`)} }catch(e){toast(e.message||'Registration failed')}finally{if(btn){btn.disabled=false;btn.textContent=window.regRole==='CUSTOMER'?'Create customer account':'Submit for admin approval'}}}
function showOtpVerification(email,password,role,name){window.pendingRegistration={email,password,role,name};openModal(`<span class="eyebrow">EMAIL VERIFICATION</span><h2>Verify your email</h2><p class="muted">We sent a 6-digit OTP to <b>${esc(email)}</b>. It expires in 10 minutes.</p><input id="otpCode" class="field otp-input" inputmode="numeric" maxlength="6" placeholder="000000"><button class="btn primary wide top-gap" onclick="verifyRegistrationOtp()">Verify email</button><button class="btn ghost wide top-gap" onclick="resendRegistrationOtp()">Resend OTP</button>`)}
async function verifyRegistrationOtp(){const p=window.pendingRegistration||{};try{const r=await api('/auth/verify-email',{method:'POST',body:{email:p.email,code:$('otpCode').value}});if(p.role==='CUSTOMER'&&r.token){setSession(r);window.pendingRegistration=null;closeModal();toast('Email verified. Account ready!');dashboard()}else{window.pendingRegistration=null;closeModal();openModal(`<div class="success-panel"><div class="success-icon"><i class="ic ic-check"></i></div><span class="eyebrow">APPLICATION VERIFIED</span><h2>Thanks, ${esc(p.name)}</h2><p>Your email is verified. Your ${String(p.role||'').toLowerCase()} application is now waiting for admin approval.</p><button class="btn primary wide" onclick="closeModal()">Done</button></div>`)} }catch(e){toast(e.message)}}
async function resendRegistrationOtp(){const email=window.pendingRegistration?.email;if(!email)return;try{await api('/auth/resend-otp',{method:'POST',body:{email}});toast('New OTP sent')}catch(e){toast(e.message)}}
function compressImage(file){return new Promise((resolve,reject)=>{const img=new Image(),r=new FileReader();r.onload=()=>{img.onload=()=>{const max=1400,scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);let q=.82;const loop=()=>c.toBlob(b=>{if(!b)return reject(Error('Could not process image'));if(b.size<=900*1024||q<=.45){const fr=new FileReader();fr.onload=()=>resolve(String(fr.result));fr.readAsDataURL(b)}else{q-=.08;loop()}},'image/jpeg',q);loop()};img.onerror=reject;img.src=String(r.result)};r.onerror=reject;r.readAsDataURL(file)})}
function guessEmail(v){const s=(v||'').trim();return s.includes('@')?s:null}
function fileData(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result));r.onerror=rej;r.readAsDataURL(file)})}
async function checkout(){if(!cart.length)return;if(!me){showLogin('Please sign in as a customer to checkout.');return}if(me.role!=='CUSTOMER'){toast('Only customer accounts can place orders.');return}openModal(`<span class="eyebrow">SECURE CHECKOUT</span><h2>Choose your delivery location</h2><p class="muted">Use GPS for the most accurate distance-based delivery fee, or enter your address manually.</p><div class="location-options"><button class="location-card" onclick="detectCheckoutLocation()"><span><i class="ic ic-pin"></i></span><div><b>Use current location</b><small>GPS + automatic address</small></div><i>→</i></button><button class="location-card secondary" onclick="enableManualLocation()"><span><i class="ic ic-search"></i></span><div><b>Enter location manually</b><small>Street, area and city</small></div><i>→</i></button></div><div id="checkoutLoc" class="location-status">No location selected</div><textarea id="checkoutAddress" class="field" rows="3" placeholder="House / Road, Area, City"></textarea><button id="manualGeo" class="btn small" onclick="geocodeManualAddress()">Find this address on map</button>${cart.some(x=>x.prescriptionRequired)?'<div class="verification-upload"><b>Prescription required</b><p>Upload a clear prescription image or PDF for prescription medicines.</p><input id="rxFile" type="file" accept="image/*,.pdf"><small>Maximum 3 MB.</small><small>Prescription will be reviewed manually by the pharmacy before dispensing.</small></div>':''}<div class="payment-choice"><b>Payment method</b><label><input type="radio" name="checkoutPayment" value="COD" checked> Cash on Delivery</label><label><input type="radio" name="checkoutPayment" value="SSLCOMMERZ"> Online payment · SSLCommerz (bKash, cards, supported channels)</label><small>Online checkout redirects to SSLCommerz after the order is created.</small></div><input id="checkoutLat" type="hidden"><input id="checkoutLng" type="hidden"><div id="checkoutMap" class="map"><div class="map-empty"><i class="ic ic-pin"></i><span>Location preview</span></div></div><div class="checkout-foot"><div><small id="checkoutEstimate">Delivery fee will be calculated from distance</small><b id="checkoutTotal">Subtotal ${money(cartTotal())}</b></div><button class="btn primary" onclick="submitOrder()">Place order</button></div>`)}
function enableManualLocation(){const s=$('checkoutLoc');s.className='location-status';s.textContent='Manual address mode enabled';$('checkoutAddress').focus();$('checkoutMap').innerHTML='<div class="map-empty">Enter your address, then tap “Find this address on map”.</div>'}
async function geocodeManualAddress(){const q=$('checkoutAddress').value.trim();if(q.length<6){toast('Please enter a fuller street, area and city');return}try{$('checkoutLoc').textContent='Finding address…';const r=await api('/location/geocode?q='+encodeURIComponent(q));if(!r.latitude){throw Error('Address could not be located. You can still place the order with the entered address.')}$('checkoutLat').value=r.latitude;$('checkoutLng').value=r.longitude;$('checkoutAddress').value=r.display||q;$('checkoutMap').innerHTML=`<iframe src="${mapEmbed(r.latitude,r.longitude)}"></iframe>`;$('checkoutLoc').className='location-status success';$('checkoutLoc').innerHTML='<i class="ic ic-check"></i> Address located';await previewDelivery(r.latitude,r.longitude)}catch(e){$('checkoutLoc').className='location-status error';$('checkoutLoc').textContent=e.message||'Could not locate address'}}
async function detectCheckoutLocation(){const s=$('checkoutLoc');try{s.className='location-status loading';s.textContent='Detecting precise location…';const p=await position(),g=await reverseGeo(p.coords.latitude,p.coords.longitude);$('checkoutLat').value=p.coords.latitude;$('checkoutLng').value=p.coords.longitude;$('checkoutAddress').value=g.display;$('checkoutMap').innerHTML=`<iframe src="${mapEmbed(p.coords.latitude,p.coords.longitude)}"></iframe>`;s.className='location-status success';s.innerHTML=`<i class="ic ic-check"></i> GPS location detected · ±${Math.round(p.coords.accuracy||0)}m`;await previewDelivery(p.coords.latitude,p.coords.longitude)}catch(e){s.className='location-status error';s.textContent=gpsError(e);enableManualLocation()}}
async function previewDelivery(lat,lng){try{const p=await api('/pharmacies/'+cart[0].pharmacyId);const km=distanceKm(p.latitude,p.longitude,lat,lng),fee=calcDeliveryFee(km),mins=Math.max(25,Math.min(90,20+Math.ceil(km*5)));$('checkoutEstimate').textContent=`${km.toFixed(1)} km · Delivery ৳${fee} · Est. ${mins} min`;$('checkoutTotal').textContent=`Total ${money(cartTotal()+fee)}`}catch(e){}}
function distanceKm(a,b,c,d){const R=6371,rad=Math.PI/180,x=(c-a)*rad,y=(d-b)*rad,z=Math.sin(x/2)**2+Math.cos(a*rad)*Math.cos(c*rad)*Math.sin(y/2)**2;return R*2*Math.atan2(Math.sqrt(z),Math.sqrt(1-z))}
function calcDeliveryFee(km){if(km<=2)return 40;if(km<=5)return 50;if(km<=8)return 65;if(km<=12)return 85;if(km<=16)return 110;return 140}
async function submitOrder(){if(!token||!me){showLogin('Please sign in with a verified customer account before placing an order.');return}if(me.role!=='CUSTOMER'){toast('Please sign in with a customer account to place an order.');return}const address=$('checkoutAddress').value.trim();if(!address){toast('Please enter your delivery address');return}let lat=Number($('checkoutLat').value),lng=Number($('checkoutLng').value);if(!lat||!lng){await geocodeManualAddress();lat=Number($('checkoutLat').value);lng=Number($('checkoutLng').value);if(!lat||!lng){toast('Please find your manual address on the map before placing the order');return}}try{let rx='';const f=$('rxFile')?.files?.[0];if(f){if(f.size>3*1024*1024)throw Error('Prescription must be under 3 MB');rx=await uploadOptionalImage('rxFile','prescriptions','')}if(cart.some(x=>x.prescriptionRequired)&&!rx)throw Error('Please upload the required prescription');const p=await api('/pharmacies/'+cart[0].pharmacyId);const km=distanceKm(p.latitude,p.longitude,lat,lng),fee=calcDeliveryFee(km);const order=await api('/orders',{method:'POST',body:{pharmacyId:cart[0].pharmacyId,deliveryAddress:address,customerLatitude:lat,customerLongitude:lng,total:cartTotal(),deliveryFee:fee,paymentMethod:'COD',paymentStatus:'PENDING',prescriptionDocument:rx,items:cart.flatMap(x=>Array(x.qty).fill(x.name))}});const paymentMethod=document.querySelector('input[name=checkoutPayment]:checked')?.value||'COD';if(paymentMethod==='SSLCOMMERZ'){const pay=await api(`/payments/${order.id}/sslcommerz/initiate`,{method:'POST',body:{}});cart=[];saveCart();location.href=pay.gatewayUrl;return}cart=[];saveCart();closeModal();openModal(`<div class="success-panel"><div class="success-icon"><i class="ic ic-check"></i></div><span class="eyebrow">ORDER CONFIRMED</span><h2>Order #${esc(order.id?.slice(-6)||'')}</h2><p>Your order has been sent to the pharmacy.</p><div class="order-summary"><div><span>Delivery distance</span><b>${Number(order.distanceKm||km).toFixed(1)} km</b></div><div><span>Delivery fee</span><b>${money(order.deliveryFee||fee)}</b></div><div><span>Estimated delivery</span><b>${order.estimatedDeliveryMinutes||Math.max(25,20+Math.ceil(km*5))} min</b></div><div><span>Payment</span><b>Cash on Delivery</b></div></div><button class="btn primary wide" onclick="closeModal();dashboard('orders')">Track my order</button></div>`)}catch(e){toast(e.message||'Could not place order')}}
function dashboard(page='overview'){if(!me)return showLogin();location.hash='#dashboard';renderDashboard(page)}
async function renderDashboard(page='overview'){if(!me){home();return}if(me.role==='CUSTOMER')return customerDash(page);if(me.role==='PHARMACY')return pharmacyDash(page);if(me.role==='RIDER')return riderDash(page);return adminDash(page)}
function shell(title,body,active){return `<div class="dash"><aside class="side"><a class="brand" href="/"><span class="logo"><i class="ic ic-plus"></i></span>Medi<em>Panda</em></a><small>${esc(me.role)} PANEL</small><div class="side-links"><button class="${active==='overview'?'active':''}" onclick="dashboard('overview')"><i class="ic ic-grid"></i> Overview</button><button class="${active==='orders'?'active':''}" onclick="dashboard('orders')"><i class="ic ic-list"></i> Orders</button>${me.role==='CUSTOMER'?'<button onclick="location.href=\'/\'"><i class="ic ic-home"></i> Shop</button>':''}${me.role==='PHARMACY'?'<button class="'+(active==='medicines'?'active':'')+'" onclick="dashboard(\'medicines\')"><i class="ic ic-pill"></i> Medicines</button><button class="'+(active==='settings'?'active':'')+'" onclick="dashboard(\'settings\')"><i class="ic ic-sliders"></i> Pharmacy profile</button>':''}${me.role==='RIDER'?'<button class="'+(active==='deliveries'?'active':'')+'" onclick="dashboard(\'deliveries\')"><i class="ic ic-bike"></i> Deliveries</button><button onclick="dashboard(\'location\')"><i class="ic ic-pin"></i> My location</button>':''}${me.role==='ADMIN'?'<button class="'+(active==='verification'?'active':'')+'" onclick="dashboard(\'verification\')"><i class="ic ic-shield"></i> Verification</button><button class="'+(active==='users'?'active':'')+'" onclick="dashboard(\'users\')"><i class="ic ic-users"></i> Users</button><button class="'+(active==='riders'?'active':'')+'" onclick="dashboard(\'riders\')"><i class="ic ic-bike"></i> Riders</button><button class="'+(active==='pharmacies'?'active':'')+'" onclick="dashboard(\'pharmacies\')"><i class="ic ic-clinic"></i> Pharmacies</button><button class="'+(active==='medicines'?'active':'')+'" onclick="dashboard(\'medicines\')"><i class="ic ic-pill"></i> Medicines</button><button class="'+(active==='data'?'active':'')+'" onclick="dashboard(\'data\')"><i class="ic ic-layers"></i> Operations</button><button class="'+(active==='reports'?'active':'')+'" onclick="dashboard(\'reports\')"><i class="ic ic-file"></i> Reports</button><button class="'+(active==='settings'?'active':'')+'" onclick="dashboard(\'settings\')"><i class="ic ic-sliders"></i> Site settings</button>':''}${me.role!=='ADMIN'?'<button class="'+(active==='reports'?'active':'')+'" onclick="dashboard(\'reports\')"><i class="ic ic-file"></i> Report to Admin</button>':''}<button onclick="editProfile()"><i class="ic ic-user"></i> Account & profile</button></div><button class="btn wide" onclick="logout()">Logout</button></aside><main class="dash-main"><header class="dash-head"><div><b>${esc(title)}</b><span>${esc(me.email||me.phone||'')}</span></div><button class="btn notification-btn" onclick="notifications()"><i class="ic ic-bell"></i> Notifications <span id="notifBadge" class="notif-badge" hidden></span></button><button class="btn" onclick="location.href='/'">Storefront</button></header><div class="dash-content">${body}</div></main></div>`}
async function customerDash(page){try{const os=await api('/customer/orders');let body=`<div class="page-title"><span class="eyebrow">CUSTOMER</span><h1>Hello, ${esc(me.name)}</h1><p>Manage orders, tracking and delivery conversations.</p></div>`;body+=page==='reports'?reportPanel():page==='orders'?`<h2>My orders</h2>${ordersHtml(os)}`:`<div class="stats"><div><small>Total orders</small><b>${os.length}</b></div><div><small>Active deliveries</small><b>${os.filter(o=>!['DELIVERED','CANCELLED'].includes(o.status)).length}</b></div><div><small>Cart items</small><b>${cart.reduce((a,x)=>a+x.qty,0)}</b></div></div><h2>Recent orders</h2>${ordersHtml(os.slice(0,4))}`;$('app').innerHTML=shell('Customer dashboard',body,page)}catch(e){showDashboardError(e)}}
function ordersHtml(os){if(!os.length)return'<div class="empty">No orders yet. <a onclick="location.href='/'">Browse pharmacies →</a></div>';return os.map(o=>`<article class="order"><div class="order-top"><div><b>Order #${esc(o.id?.slice(-6))}</b><small>${o.createdAt?new Date(o.createdAt).toLocaleString():''}</small></div><span class="status">${esc((o.status||'').replaceAll('_',' '))}</span></div><p>${(o.items||[]).map(esc).join(' · ')}</p><div class="order-bottom"><span><i class="ic ic-pin"></i> ${esc(o.deliveryAddress)}</span><b>${money((o.total||0)+(o.deliveryFee||0))}</b></div><div class="order-meta"><span><i class="ic ic-truck"></i> Delivery ৳${Number(o.deliveryFee||0).toFixed(0)}</span><span><i class="ic ic-ruler"></i> ${Number(o.distanceKm||0).toFixed(1)} km</span><span><i class="ic ic-clock"></i> Est. ${o.estimatedDeliveryMinutes||'—'} min</span><span><i class="ic ic-cash"></i> Cash on Delivery</span></div><div class="actions"><button class="btn" onclick="trackOrder('${o.id}')"><i class="ic ic-pin"></i> Track</button><button class="btn" onclick="openChat('${o.id}')"><i class="ic ic-chat"></i> Chat</button>${o.status==='DELIVERED'?`<button class="btn" onclick="openReview('${o.id}')">★ Review</button><button class="btn" onclick="invoice('${o.id}')"><i class="ic ic-receipt"></i> Invoice</button>`:''}</div></article>`).join('')}
async function pharmacyDash(page){try{const [p,os,ms]=await Promise.all([api('/pharmacy/me'),api('/pharmacy/orders'),api('/pharmacy/medicines')]);let body=`<div class="page-title"><span class="eyebrow">PHARMACY</span><h1>${esc(p.name)}</h1><p>${esc([p.street,p.area,p.locationAddress].filter(Boolean).join(', '))}</p></div>`;if(page==='reports')body+=reportPanel();else if(page==='medicines')body+=pharmacyMedicinePanel(ms);else if(page==='settings')body+=pharmacySettings(p);else body+=`<div class="stats"><div><small>Catalogue</small><b>${ms.length}</b></div><div><small>New orders</small><b>${os.filter(o=>o.status==='PENDING').length}</b></div><div><small>Preparing</small><b>${os.filter(o=>o.status==='PREPARING').length}</b></div></div><h2>Incoming orders</h2>${pharmacyOrdersHtml(os)}`;$('app').innerHTML=shell('Pharmacy workspace',body,page)}catch(e){showDashboardError(e)}}
function pharmacyOrdersHtml(os){if(!os.length)return'<div class="empty">No orders yet.</div>';return os.map(o=>`<article class="order"><div class="order-top"><div><b>Order #${esc(o.id?.slice(-6))}</b><small>${esc(o.customerName)} · ${esc(o.deliveryAddress)}</small></div><span class="status">${esc(o.status)}</span></div><p>${(o.items||[]).map(esc).join(' · ')}</p><div class="actions">${o.status==='PENDING'?`<button class="btn" onclick="pharmacyStatus('${o.id}','CONFIRMED')">Confirm</button>`:''}${['CONFIRMED','PENDING'].includes(o.status)?`<button class="btn" onclick="pharmacyStatus('${o.id}','PREPARING')">Start preparing</button>`:''}${['PREPARING','CONFIRMED','PENDING','WAITING_FOR_RIDER'].includes(o.status)?`<button class="btn primary" onclick="markReady('${o.id}')">Ready for rider</button>`:''}<button class="btn" onclick="openChat('${o.id}')"><i class="ic ic-chat"></i> Chat customer</button></div></article>`).join('')}
async function pharmacyStatus(id,s){try{await api(`/pharmacy/orders/${id}/status/${s}`,{method:'PATCH'});toast('Order updated');dashboard('orders')}catch(e){toast(e.message)}}
async function markReady(id){try{await api(`/pharmacy/orders/${id}/ready`,{method:'PATCH'});toast('Order ready — rider request sent');dashboard('orders')}catch(e){toast(e.message)}}
function pharmacyMedicinePanel(ms){return `<div class="panel-head"><div><h2>Medicine catalogue</h2><p class="muted">Add, edit or remove products shown on your pharmacy page.</p></div><button class="btn primary" onclick="medicineForm()"><i class="ic ic-plus"></i> Add medicine</button></div><div class="admin-meds">${ms.map(m=>`<div class="admin-med"><img src="${esc(m.image)}"><div><b>${esc(m.name)}</b><small>${esc(m.genericName)} · ${esc(m.category)}</small><span>${money(m.price)} · Stock ${m.stock}</span></div><div><button class="btn" onclick='medicineForm(${JSON.stringify(m).replace(/'/g,"&#39;")})'>Edit</button><button class="btn danger" onclick="deleteMedicine('${m.id}')">Delete</button></div></div>`).join('')||'<div class="empty">No medicines yet.</div>'}</div>`}
function medicineForm(m=null){openModal(`<span class="eyebrow">CATALOGUE</span><h2>${m?'Edit':'Add'} medicine</h2><label class="label">Medicine name</label><input id="mName" class="field" value="${esc(m?.name)}"><label class="label">Generic name</label><input id="mGeneric" class="field" value="${esc(m?.genericName)}"><div class="two"><div><label class="label">Category</label><input id="mCat" class="field" value="${esc(m?.category)}"></div><div><label class="label">Manufacturer</label><input id="mMaker" class="field" value="${esc(m?.manufacturer)}"></div></div><div class="two"><div><label class="label">Price</label><input id="mPrice" class="field" type="number" value="${m?.price||''}"></div><div><label class="label">Old price</label><input id="mOld" class="field" type="number" value="${m?.oldPrice||''}"></div></div><label class="label">Stock</label><input id="mStock" class="field" type="number" value="${m?.stock||0}"><label class="label">Medicine image URL</label><input id="mImage" class="field" value="${esc(m?.image)}" placeholder="https://..."><label class="label">Or upload image to Cloudinary</label><input id="mImageFile" class="field" type="file" accept="image/*"><label class="check"><input id="mRx" type="checkbox" ${m?.prescriptionRequired?'checked':''}> Prescription required</label><button class="btn primary wide top-gap" onclick="saveMedicine('${m?.id||''}')">Save medicine</button>`)}
async function saveMedicine(id){const body={name:$('mName').value,genericName:$('mGeneric').value,category:$('mCat').value,manufacturer:$('mMaker').value,price:Number($('mPrice').value),oldPrice:Number($('mOld').value),stock:Number($('mStock').value),image:await uploadOptionalImage('mImageFile','medicines',$('mImage').value),prescriptionRequired:$('mRx').checked};try{await api(id?`/pharmacy/medicines/${id}`:'/pharmacy/medicines',{method:id?'PUT':'POST',body});closeModal();toast('Medicine saved');dashboard('medicines')}catch(e){toast(e.message)}}
async function deleteMedicine(id){if(!(await askConfirm('This medicine will be removed permanently.',{title:'Delete medicine?',confirmText:'Delete',danger:true})))return;try{await api('/pharmacy/medicines/'+id,{method:'DELETE'});toast('Medicine deleted');dashboard('medicines')}catch(e){toast(e.message)}}
function pharmacySettings(p){return `<div class="settings-grid"><div class="panel"><span class="eyebrow">PHARMACY PROFILE</span><h2>Edit pharmacy information</h2><label class="label">Pharmacy name</label><input id="phName" class="field" value="${esc(p.name)}"><label class="label">Area / City</label><input id="phArea" class="field" value="${esc(p.area)}"><label class="label">Street / Road</label><input id="phStreet" class="field" value="${esc(p.street)}"><label class="label">Description</label><textarea id="phDesc" class="field" rows="4">${esc(p.description)}</textarea><label class="label">Pharmacy image URL</label><input id="phImage" class="field" value="${esc(p.image)}"><label class="label">Or upload image to Cloudinary</label><input id="phImageFile" class="field" type="file" accept="image/*"><button class="btn primary top-gap" onclick="savePharmacyProfile()">Save profile</button></div><div class="panel"><span class="eyebrow">PICKUP LOCATION</span><h2>Update exact location</h2><p class="muted">Use the device at the pharmacy to save accurate GPS coordinates.</p><button class="location-card" onclick="pharmacyLocation()"><span><i class="ic ic-pin"></i></span><div><b>Use current location</b><small>GPS + readable address</small></div><i>→</i></button><div id="phLocStatus" class="location-status">${esc(p.locationAddress||'No GPS update yet')}</div><div class="map">${p.latitude&&p.longitude?`<iframe src="${mapEmbed(p.latitude,p.longitude)}"></iframe>`:'<div class="map-empty">Location preview</div>'}</div></div></div>`}
async function savePharmacyProfile(){try{await api('/pharmacy/profile',{method:'PUT',body:{name:$('phName').value,area:$('phArea').value,street:$('phStreet').value,description:$('phDesc').value,image:await uploadOptionalImage('phImageFile','pharmacies',$('phImage').value)}});toast('Pharmacy profile updated');dashboard('settings')}catch(e){toast(e.message)}}
async function pharmacyLocation(){try{const p=await position(),g=await reverseGeo(p.coords.latitude,p.coords.longitude);await api('/location/pharmacy',{method:'PATCH',body:{latitude:p.coords.latitude,longitude:p.coords.longitude,address:g.display}});toast('Pickup location updated');dashboard('settings')}catch(e){toast(e.message||gpsError(e))}}
async function riderDash(page){try{const [r,os]=await Promise.all([api('/rider/me'),api('/rider/orders')]);if(page==='location')return riderLocationPage(r);let body=`<div class="page-title"><span class="eyebrow">RIDER</span><h1>Delivery cockpit</h1><p>Stay online, keep GPS active and manage assigned deliveries.</p></div><div class="rider-status"><div><span class="live-dot"></span><b>${esc(r.status)}</b><small>${esc(r.locationAddress||'Location not updated')}</small></div><div><button class="btn" onclick="riderAvailability('${r.status==='AVAILABLE'?'OFFLINE':'AVAILABLE'}')">${r.status==='AVAILABLE'?'Go offline':'Go available'}</button><button class="btn primary" onclick="dashboard('location')"><i class="ic ic-pin"></i> Location</button></div></div><h2>My deliveries</h2>${riderOrdersHtml(os)}`;$('app').innerHTML=shell('Rider workspace',body,page)}catch(e){showDashboardError(e)}}
function riderOrdersHtml(os){if(!os.length)return'<div class="empty">No delivery requests right now. Keep your status available.</div>';return os.map(o=>`<article class="order"><div class="order-top"><div><b>Order #${esc(o.id?.slice(-6))}</b><small>${esc(o.deliveryAddress)}</small></div><span class="status">${esc(o.status)}</span></div><p>${(o.items||[]).map(esc).join(' · ')}</p><div class="actions">${o.status==='RIDER_REQUESTED'?`<button class="btn primary" onclick="riderAction('${o.id}','accept')"><i class="ic ic-check"></i> Accept</button><button class="btn danger" onclick="riderAction('${o.id}','reject')">Reject</button>`:''}${o.status==='RIDER_ACCEPTED'?`<button class="btn primary" onclick="riderAction('${o.id}','PICKED_UP')">Picked up</button>`:''}${o.status==='PICKED_UP'?`<button class="btn primary" onclick="riderAction('${o.id}','ON_THE_WAY')">On the way</button>`:''}${o.status==='ON_THE_WAY'?`<button class="btn primary" onclick="riderAction('${o.id}','DELIVERED')">Delivered</button>`:''}<button class="btn" onclick="openChat('${o.id}')"><i class="ic ic-chat"></i> Chat</button><button class="btn" onclick="trackOrder('${o.id}')"><i class="ic ic-pin"></i> Track</button></div></article>`).join('')}
async function riderAction(id,action){try{if(action==='accept'||action==='reject')await api(`/rider/orders/${id}/${action}`,{method:'PATCH'});else await api(`/rider/orders/${id}/status/${action}`,{method:'PATCH'});toast(action==='accept'?'Delivery accepted':action==='reject'?'Request rejected':'Delivery updated');dashboard('deliveries')}catch(e){toast(e.message)}}
async function riderAvailability(s){try{await api('/rider/status/'+s,{method:'PATCH'});toast('Rider status updated');dashboard('deliveries')}catch(e){toast(e.message)}}
function riderLocationPage(r){$('app').innerHTML=shell('Rider location',`<div class="page-title"><span class="eyebrow">LIVE GPS</span><h1>My delivery location</h1><p>Keep this page open while online. Your location is shared only for active delivery operations.</p></div><div class="location-grid"><div class="panel"><button class="location-card" onclick="startRiderGPS()"><span><i class="ic ic-pin"></i></span><div><b>Detect & start live GPS</b><small>High accuracy · updates automatically</small></div><i>→</i></button><div id="riderLocStatus" class="location-status">${esc(r.locationAddress||'GPS not active')}</div><div class="map" id="riderMap">${r.latitude&&r.longitude?`<iframe src="${mapEmbed(r.latitude,r.longitude)}"></iframe>`:'<div class="map-empty">Your live location will appear here</div>'}</div></div><div class="panel"><h2>Location safety</h2><ul class="clean-list"><li>Allow browser location permission.</li><li>Use HTTPS when deployed.</li><li>Keep GPS enabled while delivering.</li><li>Only your delivery location is shared with order participants.</li></ul></div></div>`);startRiderGPS(true)}
async function startRiderGPS(silent=false){if(!navigator.geolocation){toast('Geolocation is not supported');return}if(riderWatch!==null)navigator.geolocation.clearWatch(riderWatch);const s=$('riderLocStatus');if(s&&!silent)s.innerHTML='Detecting location…';try{const p=await position();await pushRider(p);riderWatch=navigator.geolocation.watchPosition(pushRider,e=>{if(s){s.className='location-status error';s.textContent=gpsError(e)}},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});}catch(e){if(s){s.className='location-status error';s.textContent=e.message||gpsError(e)}if(!silent)toast(e.message||gpsError(e))}}
async function pushRider(p){try{const g=await reverseGeo(p.coords.latitude,p.coords.longitude);await api('/location/rider',{method:'PATCH',body:{latitude:p.coords.latitude,longitude:p.coords.longitude,address:g.display}});const s=$('riderLocStatus');if(s){s.className='location-status success';s.innerHTML=`<i class="ic ic-check"></i> Live GPS active · ±${Math.round(p.coords.accuracy||0)}m<br><small>${esc(g.display)}</small>`}$('riderMap').innerHTML=`<iframe src="${mapEmbed(p.coords.latitude,p.coords.longitude)}"></iframe>`}catch(e){const s=$('riderLocStatus');if(s){s.className='location-status error';s.textContent=e.message}}}
async function openChat(id){if(!me)return showLogin('Sign in to use order chat.');clearInterval(chatTimer);openModal(`<div class="chat-head"><div><span class="eyebrow">ORDER CHAT</span><h2>Delivery conversation</h2><p>Customer · Pharmacy · Rider</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div id="messages" class="messages">Loading…</div><div class="compose"><input id="chatText" class="field" placeholder="Write a message…" onkeydown="if(event.key==='Enter')sendChat('${id}')"><button class="btn primary" onclick="sendChat('${id}')">Send</button></div>`);await loadChat(id);chatTimer=setInterval(()=>loadChat(id,true),3500)}
async function loadChat(id,silent=false){try{const ms=await api(`/orders/${id}/messages`);const b=$('messages');if(!b)return;b.innerHTML=ms.length?ms.map(m=>`<div class="message ${m.senderEmail===me.email?'mine':''}"><b>${esc(m.senderName)} · ${esc(m.senderRole)}</b><span>${esc(m.text)}</span><small>${m.sentAt?new Date(m.sentAt).toLocaleTimeString():''}</small></div>`).join(''):'<div class="empty">No messages yet. Start the conversation.</div>';b.scrollTop=b.scrollHeight}catch(e){if(!silent)toast(e.message)}}
async function sendChat(id){const i=$('chatText'),t=i?.value.trim();if(!t)return;try{i.disabled=true;await api(`/orders/${id}/messages`,{method:'POST',body:{text:t}});i.value='';await loadChat(id,true)}catch(e){toast(e.message)}finally{i.disabled=false}}
async function trackOrder(id){clearInterval(trackTimer);if(trackMap){trackMap.remove();trackMap=null}openModal(`<div class="chat-head"><div><span class="eyebrow">LIVE TRACKING</span><h2>Order #${esc(id.slice(-6))}</h2><p id="trackStatus">Loading…</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div id="trackMap" class="map large"><div class="map-empty">Loading location…</div></div><div class="actions"><a id="googleMap" class="btn" target="_blank" rel="noopener noreferrer">OpenStreetMap <i class="ic ic-external"></i></a><button class="btn" onclick="loadTrack('${id}')">Refresh</button><button class="btn primary" onclick="openChat('${id}')"><i class="ic ic-chat"></i> Chat</button></div>`);await loadTrack(id);trackTimer=setInterval(()=>loadTrack(id,true),7000)}
let trackMap=null,trackLayer=null,trackFitted=false;
async function loadTrack(id,silent=false){try{const d=await api('/location/order/'+id),r=d.rider,lat=r?.latitude||d.customerLatitude,lng=r?.longitude||d.customerLongitude;$('trackStatus').textContent=`${(d.status||'').replaceAll('_',' ')} · ${d.deliveryAddress||''}`;if(!(lat&&lng))return;$('googleMap').href=mapsLink(lat,lng);if(!window.L){$('trackMap').innerHTML=`<iframe src="${mapEmbed(lat,lng)}"></iframe>`;return}
const el=$('trackMap');if(!trackMap||trackMap._container!==el){el.innerHTML='';trackMap=L.map(el).setView([lat,lng],14);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(trackMap);trackLayer=L.layerGroup().addTo(trackMap);trackFitted=false}
trackLayer.clearLayers();const pin=(la,ln,label)=>L.marker([la,ln]).bindTooltip(label).addTo(trackLayer);const bounds=[];
if(d.customerLatitude){pin(d.customerLatitude,d.customerLongitude,'Delivery address');bounds.push([d.customerLatitude,d.customerLongitude])}
if(d.pharmacy?.latitude){pin(d.pharmacy.latitude,d.pharmacy.longitude,d.pharmacy.name||'Pharmacy');bounds.push([d.pharmacy.latitude,d.pharmacy.longitude])}
if(r?.latitude){pin(r.latitude,r.longitude,'Rider '+(r.name||''));bounds.push([r.latitude,r.longitude])}
try{const rt=await api('/location/order/'+id+'/route');const line=L.geoJSON(rt.geometry,{style:{color:'#12a066',weight:5,opacity:.85}}).addTo(trackLayer);if(rt.durationMin)$('trackStatus').textContent+=` · ${rt.distanceKm} km · ~${rt.durationMin} min`;if(!trackFitted){trackMap.fitBounds(line.getBounds(),{padding:[30,30]});trackFitted=true}}catch(e){if(!trackFitted&&bounds.length){trackMap.fitBounds(bounds,{padding:[30,30],maxZoom:16});trackFitted=true}}
}catch(e){if(!silent)toast(e.message)}}
function editProfile(){openModal(`<span class="eyebrow">ACCOUNT SETTINGS</span><h2>Profile & security</h2><p class="muted">Update your name, email, password and profile picture.</p><label class="label">Full name</label><input id="accName" class="field" value="${esc(me.name)}"><label class="label">Gmail / Email</label><input id="accEmail" type="email" class="field" value="${esc(me.email||'')}" placeholder="you@gmail.com"><label class="label">New password</label><input id="accPass" type="password" class="field" placeholder="Leave blank to keep current"><label class="label">Profile picture</label><input id="accPic" class="field" type="file" accept="image/*"><small class="muted">Image only, maximum 1 MB.</small><button class="btn primary wide top-gap" onclick="saveProfile()">Save account changes</button>`)}
async function saveProfile(){try{const f=new FormData();f.append('name',$('accName').value);f.append('email',$('accEmail').value);f.append('password',$('accPass').value);if($('accPic').files[0])f.append('profilePicture',$('accPic').files[0]);const r=await api('/auth/me/profile',{method:'PATCH',body:f});if(r.session){setSession(r.session);me.profilePicture=r.user.profilePicture;localStorage.setItem('mp_user',JSON.stringify(me));}closeModal();toast(r.user?.emailVerified===false?'Account updated. Verify your email if you changed it.':'Account updated');dashboard()}catch(e){toast(e.message)}}
function reportPanel(){return `<div class="panel report-panel"><span class="eyebrow">SUPPORT</span><h2>Report an issue to Admin</h2><p class="muted">Tell us about an order, account, pharmacy, rider or technical problem.</p><label class="label">Subject</label><input id="reportSubject" class="field" maxlength="100" placeholder="e.g. Order issue / Payment / Delivery"><label class="label">Message</label><textarea id="reportMessage" class="field" rows="6" maxlength="1000" placeholder="Describe the issue clearly..."></textarea><button class="btn primary top-gap" onclick="submitReport()">Send report</button></div><div class="panel top-gap"><div class="panel-head"><div><h2>My reports</h2><p class="muted">Track replies from Admin.</p></div><button class="btn" onclick="loadMyReports()">Refresh</button></div><div id="myReports"><div class="empty">Loading reports…</div></div></div>`}
async function submitReport(){try{await api('/reports',{method:'POST',body:{subject:$('reportSubject').value,message:$('reportMessage').value}});$('reportSubject').value='';$('reportMessage').value='';toast('Report sent to Admin');loadMyReports()}catch(e){toast(e.message)}}
async function loadMyReports(){try{const rs=await api('/reports');const el=$('myReports');if(!el)return;el.innerHTML=rs.length?rs.map(r=>`<article class="order"><div class="order-top"><div><b>${esc(r.subject)}</b><small>${r.createdAt?new Date(r.createdAt).toLocaleString():''}</small></div><span class="status">${esc(r.status)}</span></div><p>${esc(r.message)}</p>${r.adminReply?`<div class="notice"><b>Admin reply</b><p>${esc(r.adminReply)}</p></div>`:''}</article>`).join(''):'<div class="empty">No reports submitted yet.</div>'}catch(e){toast(e.message)}}
async function adminDash(page){try{const d=await api('/admin/dashboard');let body=`<div class="page-title"><span class="eyebrow">ADMIN CONTROL CENTER</span><h1>Everything in MediPanda, one place.</h1><p>Manage the storefront, partners, medicines, orders, reports and platform settings.</p></div>`;
if(page==='verification'){const rs=await api('/admin/verification-requests');body+=`<h2>Pending verification</h2><div class="verification-list">${rs.map(u=>`<article class="verification"><div><span class="role-badge">${esc(u.role)}</span><h3>${esc(u.name)}</h3><p>${esc(u.email||u.phone||'')} · ${esc(u.phone||'')}</p><small>Document: ${esc(u.verificationDocumentType||'Verification')}</small>${u.verificationDocument?`<a class="doc-link" href="${esc(u.verificationDocument)}" target="_blank">View uploaded document <i class="ic ic-external"></i></a>`:''}</div><div class="actions"><button class="btn primary" onclick="reviewUser('${u.id}','approve')">Approve</button><button class="btn danger" onclick="reviewUser('${u.id}','reject')">Reject</button></div></article>`).join('')||'<div class="empty">No pending applications.</div>'}</div>`}
else if(page==='users'){const us=await api('/admin/users');body+=`<div class="panel-head"><div><h2>Users & partners</h2><p class="muted">Enable, disable and review every account.</p></div></div><div class="table-wrap"><table><tr><th>Name</th><th>Contact</th><th>Role</th><th>Verification</th><th>Account</th><th></th></tr>${us.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email||u.phone||'')}</td><td>${esc(u.role)}</td><td>${esc(u.verificationStatus||'-')}</td><td>${u.enabled?'Active':'Disabled'}</td><td>${u.role!=='ADMIN'?`<button class="btn" onclick="toggleUser('${u.id}')">${u.enabled?'Disable':'Enable'}</button>`:''}</td></tr>`).join('')}</table></div>`}
else if(page==='riders'){const rs=await api('/admin/riders');body+=`<h2>Rider fleet</h2><div class="table-wrap"><table><tr><th>Name</th><th>Phone</th><th>Status</th><th>Location</th><th>Earnings</th></tr>${rs.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.phone)}</td><td>${esc(r.status)}</td><td>${esc(r.locationAddress||'Not updated')}</td><td>${money(r.earnings)}</td></tr>`).join('')}</table></div>`}
else if(page==='data'){const [os,ps,ms,rs]=await Promise.all([api('/admin/orders'),api('/admin/pharmacies'),api('/admin/medicines'),api('/admin/riders')]);body+=`<div class="admin-cards"><button onclick="dashboard('pharmacies')"><b><i class="ic ic-clinic"></i> Manage pharmacies</b><span>${ps.length} pharmacies · edit every public field</span></button><button onclick="dashboard('medicines')"><b><i class="ic ic-pill"></i> Manage medicines</b><span>${ms.length} medicines · price, stock, image, pharmacy</span></button></div><h2 class="top-gap">Order operations</h2><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Status</th><th>Rider</th><th>Total</th><th>Assign</th></tr>${os.map(o=>`<tr><td>#${esc(o.id?.slice(-6))}</td><td>${esc(o.customerName)}</td><td><select class="field" onchange="adminOrderStatus('${o.id}',this.value)"><option value="${esc(o.status)}">${esc(o.status)}</option>${['PENDING','CONFIRMED','PREPARING','READY_FOR_PICKUP','WAITING_FOR_RIDER','RIDER_REQUESTED','RIDER_ACCEPTED','PICKED_UP','ON_THE_WAY','DELIVERED','CANCELLED'].filter(x=>x!==o.status).map(x=>`<option value="${x}">${x}</option>`).join('')}</select></td><td>${esc(o.riderId||'Unassigned')}</td><td>${money((o.total||0)+(o.deliveryFee||0))}</td><td><select class="field" onchange="adminAssign('${o.id}',this.value)"><option value="">Select rider</option>${rs.filter(r=>r.status==='AVAILABLE'||r.id===o.riderId).map(r=>`<option value="${r.id}">${esc(r.name)} · ${r.status}</option>`).join('')}</select></td></tr>`).join('')}</table></div>`}
else if(page==='pharmacies'){const ps=await api('/admin/pharmacies');body+=`<div class="panel-head"><div><h2>Pharmacy manager</h2><p class="muted">Everything customers see can be edited here.</p></div><button class="btn primary" onclick="adminPharmacyForm()"><i class="ic ic-plus"></i> Add pharmacy</button></div><div class="admin-meds">${ps.map(p=>`<div class="admin-med"><img src="${esc(p.image)}"><div><b>${esc(p.name)}</b><small>${esc(p.street||'')} · ${esc(p.area||'')}</small><span>${p.open?'Open':'Closed'} · ${esc(p.deliveryTime||'')}</span></div><div><button class="btn" onclick='adminPharmacyForm(${JSON.stringify(p).replace(/'/g,"&#39;")})'>Edit</button><button class="btn danger" onclick="deleteAdminPharmacy('${p.id}')">Delete</button></div></div>`).join('')||'<div class="empty">No pharmacies.</div>'}</div>`}
else if(page==='medicines'){const [ms,ps]=await Promise.all([api('/admin/medicines'),api('/admin/pharmacies')]);body+=`<div class="panel-head"><div><h2>Medicine manager</h2><p class="muted">Edit products, pricing, stock and images across the site.</p></div><button class="btn primary" onclick='adminMedicineForm(null,${JSON.stringify(ps).replace(/'/g,"&#39;")})'><i class="ic ic-plus"></i> Add medicine</button></div><div class="admin-meds">${ms.map(m=>`<div class="admin-med"><img src="${esc(m.image)}"><div><b>${esc(m.name)}</b><small>${esc(m.genericName||'')} · ${esc(m.category||'')}</small><span>${money(m.price)} · Stock ${m.stock}</span></div><div><button class="btn" onclick='adminMedicineForm(${JSON.stringify(m).replace(/'/g,"&#39;")},${JSON.stringify(ps).replace(/'/g,"&#39;")})'>Edit</button><button class="btn danger" onclick="deleteAdminMedicine('${m.id}')">Delete</button></div></div>`).join('')||'<div class="empty">No medicines.</div>'}</div>`}
else if(page==='reports'){const rs=await api('/admin/reports');body+=`<h2>Reports from every role</h2><div class="verification-list">${rs.map(r=>`<article class="verification"><div><span class="role-badge">${esc(r.role)}</span><h3>${esc(r.subject)}</h3><p>${esc(r.userName)} · ${r.createdAt?new Date(r.createdAt).toLocaleString():''}</p><p>${esc(r.message)}</p>${r.adminReply?`<div class="notice"><b>Current reply:</b> ${esc(r.adminReply)}</div>`:''}</div><div class="actions"><select id="rs_${r.id}" class="field"><option ${r.status==='OPEN'?'selected':''}>OPEN</option><option ${r.status==='IN_PROGRESS'?'selected':''}>IN_PROGRESS</option><option ${r.status==='CLOSED'?'selected':''}>CLOSED</option></select><input id="rr_${r.id}" class="field" placeholder="Admin reply" value="${esc(r.adminReply||'')}"><button class="btn primary" onclick="updateReport('${r.id}')">Save</button></div></article>`).join('')||'<div class="empty">No reports yet.</div>'}</div>`}
else if(page==='settings'){const s=await api('/site');body+=`<div class="panel"><span class="eyebrow">SITE CONTROL</span><h2>Global storefront settings</h2><p class="muted">Change the public-facing content without touching source code.</p><label class="label">Site name</label><input id="siteName" class="field" value="${esc(s.siteName)}"><label class="label">Tagline</label><input id="siteTagline" class="field" value="${esc(s.tagline)}"><label class="label">Hero title</label><input id="siteHeroTitle" class="field" value="${esc(s.heroTitle)}"><label class="label">Hero text</label><textarea id="siteHeroText" class="field" rows="4">${esc(s.heroText)}</textarea><label class="label">Hero video URL</label><input id="siteVideo" class="field" value="${esc(s.heroVideoUrl)}"><label class="label">Logo URL</label><input id="siteLogo" class="field" value="${esc(s.logoUrl||'')}"><div class="two"><div><label class="label">Contact email</label><input id="siteEmail" class="field" value="${esc(s.contactEmail||'')}"></div><div><label class="label">Contact phone</label><input id="sitePhone" class="field" value="${esc(s.contactPhone||'')}"></div></div><label class="label">Footer text</label><input id="siteFooter" class="field" value="${esc(s.footerText||'')}"><label class="check"><input id="siteMaintenance" type="checkbox" ${s.maintenanceMode?'checked':''}> Maintenance mode</label><button class="btn primary top-gap" onclick="saveSiteSettings()">Save site settings</button></div>`}
else {body+=`<div class="stats"><div><small>Users</small><b>${d.users}</b></div><div><small>Pharmacies</small><b>${d.pharmacies}</b></div><div><small>Medicines</small><b>${d.medicines}</b></div><div><small>Orders</small><b>${d.orders}</b></div><div><small>Open reports</small><b>${d.openReports||0}</b></div></div><div class="admin-cards"><button onclick="dashboard('verification')"><b><i class="ic ic-shield"></i> Verification</b><span>Review NID / Trade Licence applications</span></button><button onclick="dashboard('data')"><b><i class="ic ic-truck"></i> Operations</b><span>Orders and rider assignment</span></button><button onclick="dashboard('pharmacies')"><b><i class="ic ic-clinic"></i> Pharmacies</b><span>Full public pharmacy control</span></button><button onclick="dashboard('medicines')"><b><i class="ic ic-pill"></i> Medicines</b><span>Global catalogue management</span></button><button onclick="dashboard('users')"><b><i class="ic ic-users"></i> Users</b><span>Account management</span></button><button onclick="dashboard('reports')"><b><i class="ic ic-file"></i> Reports</b><span>Handle reports from all roles</span></button><button onclick="dashboard('settings')"><b><i class="ic ic-sliders"></i> Site settings</b><span>Hero, branding, contact and footer</span></button><button onclick="dashboard('riders')"><b><i class="ic ic-pin"></i> Rider fleet</b><span>Live rider status and locations</span></button></div>`}
$('app').innerHTML=shell('Admin control center',body,page);if(page==='reports'&&$('myReports'))loadMyReports();}catch(e){showDashboardError(e)}}
function adminPharmacyForm(p=null){openModal(`<span class="eyebrow">PHARMACY MANAGER</span><h2>${p?'Edit':'Add'} pharmacy</h2><label class="label">Name</label><input id="apName" class="field" value="${esc(p?.name)}"><label class="label">Area / City</label><input id="apArea" class="field" value="${esc(p?.area)}"><label class="label">Street / Road</label><input id="apStreet" class="field" value="${esc(p?.street)}"><label class="label">Image URL</label><input id="apImage" class="field" value="${esc(p?.image)}"><label class="label">Or upload image to Cloudinary</label><input id="apImageFile" class="field" type="file" accept="image/*"><label class="label">Description</label><textarea id="apDesc" class="field" rows="3">${esc(p?.description)}</textarea><div class="two"><input id="apRating" class="field" placeholder="Rating" value="${esc(p?.rating)}"><input id="apTime" class="field" placeholder="Delivery time" value="${esc(p?.deliveryTime)}"></div><label class="check"><input id="apOpen" type="checkbox" ${p?.open?'checked':''}> Open</label><label class="label">Location address</label><input id="apLoc" class="field" value="${esc(p?.locationAddress)}"><div class="two"><input id="apLat" class="field" placeholder="Latitude" value="${p?.latitude||''}"><input id="apLng" class="field" placeholder="Longitude" value="${p?.longitude||''}"></div><button class="btn primary wide top-gap" onclick="saveAdminPharmacy(${p?`'${p.id}'`:'null'})">Save pharmacy</button>`)}
async function saveAdminPharmacy(id){try{const body={name:$('apName').value,area:$('apArea').value,street:$('apStreet').value,image:await uploadOptionalImage('apImageFile','pharmacies',$('apImage').value),description:$('apDesc').value,rating:$('apRating').value,deliveryTime:$('apTime').value,open:$('apOpen').checked,locationAddress:$('apLoc').value,latitude:Number($('apLat').value)||0,longitude:Number($('apLng').value)||0};await api(id?`/admin/pharmacies/${id}`:'/admin/pharmacies',{method:id?'PUT':'POST',body});closeModal();toast('Pharmacy saved');dashboard('pharmacies')}catch(e){toast(e.message)}}
async function deleteAdminPharmacy(id){if(!(await askConfirm('This pharmacy will be removed permanently.',{title:'Delete pharmacy?',confirmText:'Delete',danger:true})))return;try{await api('/admin/pharmacies/'+id,{method:'DELETE'});toast('Pharmacy deleted');dashboard('pharmacies')}catch(e){toast(e.message)}}
function adminMedicineForm(m,ps){openModal(`<span class="eyebrow">MEDICINE MANAGER</span><h2>${m?'Edit':'Add'} medicine</h2><label class="label">Pharmacy</label><select id="amPh" class="field">${ps.map(p=>`<option value="${p.id}" ${m?.pharmacyId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label class="label">Name</label><input id="amName" class="field" value="${esc(m?.name)}"><label class="label">Generic name</label><input id="amGeneric" class="field" value="${esc(m?.genericName)}"><label class="label">Category</label><input id="amCat" class="field" value="${esc(m?.category)}"><label class="label">Manufacturer</label><input id="amMan" class="field" value="${esc(m?.manufacturer)}"><div class="two"><input id="amPrice" class="field" type="number" value="${m?.price||''}" placeholder="Price"><input id="amOld" class="field" type="number" value="${m?.oldPrice||''}" placeholder="Old price"></div><input id="amStock" class="field" type="number" value="${m?.stock??0}" placeholder="Stock"><label class="label">Image URL</label><input id="amImage" class="field" value="${esc(m?.image)}"><label class="label">Or upload image to Cloudinary</label><input id="amImageFile" class="field" type="file" accept="image/*"><label class="check"><input id="amRx" type="checkbox" ${m?.prescriptionRequired?'checked':''}> Prescription required</label><button class="btn primary wide top-gap" onclick="saveAdminMedicine(${m?`'${m.id}'`:'null'})">Save medicine</button>`)}
async function saveAdminMedicine(id){try{const body={pharmacyId:$('amPh').value,name:$('amName').value,genericName:$('amGeneric').value,category:$('amCat').value,manufacturer:$('amMan').value,price:Number($('amPrice').value),oldPrice:Number($('amOld').value)||0,stock:Number($('amStock').value)||0,image:await uploadOptionalImage('amImageFile','medicines',$('amImage').value),prescriptionRequired:$('amRx').checked};await api(id?`/admin/medicines/${id}`:'/admin/medicines',{method:id?'PUT':'POST',body});closeModal();toast('Medicine saved');dashboard('medicines')}catch(e){toast(e.message)}}
async function deleteAdminMedicine(id){if(!(await askConfirm('This medicine will be removed permanently.',{title:'Delete medicine?',confirmText:'Delete',danger:true})))return;try{await api('/admin/medicines/'+id,{method:'DELETE'});toast('Medicine deleted');dashboard('medicines')}catch(e){toast(e.message)}}
async function updateReport(id){try{await api('/admin/reports/'+id,{method:'PATCH',body:{status:$('rs_'+id).value,adminReply:$('rr_'+id).value}});toast('Report updated');dashboard('reports')}catch(e){toast(e.message)}}
async function saveSiteSettings(){try{await api('/admin/site',{method:'PUT',body:{siteName:$('siteName').value,tagline:$('siteTagline').value,heroTitle:$('siteHeroTitle').value,heroText:$('siteHeroText').value,heroVideoUrl:$('siteVideo').value,logoUrl:$('siteLogo').value,contactEmail:$('siteEmail').value,contactPhone:$('sitePhone').value,footerText:$('siteFooter').value,maintenanceMode:$('siteMaintenance').checked}});toast('Site settings saved');dashboard('settings')}catch(e){toast(e.message)}}
async function reviewUser(id,a){try{if(a==='reject'){const reason=await askText('Reject application',{placeholder:'Reason shown to the applicant',confirmText:'Reject',danger:true,defaultValue:'Please submit clearer/correct documents.'});if(reason===null)return;await api(`/admin/verification/${id}/reject`,{method:'PATCH',body:{reason}})}else await api(`/admin/verification/${id}/approve`,{method:'PATCH'});toast(a==='approve'?'Application approved':'Application rejected');dashboard('verification')}catch(e){toast(e.message)}}
async function toggleUser(id){try{await api('/admin/users/'+id+'/toggle',{method:'PATCH'});dashboard('users')}catch(e){toast(e.message)}}
async function adminOrderStatus(id,status){try{await api('/admin/orders/'+id+'/status',{method:'PATCH',body:{status}});toast('Order status updated');dashboard('data')}catch(e){toast(e.message)}}
async function adminAssign(oid,rid){if(!rid)return;try{await api(`/admin/orders/${oid}/assign/${rid}`,{method:'PATCH'});toast('Rider assigned');dashboard('data')}catch(e){toast(e.message)}}
async function searchHome(){const q=$('homeSearch').value.trim();if(!q)return;location.hash='#medicines';await loadHomeMeds();const ms=await api('/medicines?search='+encodeURIComponent(q));$('medicineGrid').innerHTML=ms.map(m=>medCard(m)).join('')||'<div class="empty">No matching medicines.</div>'}
async function openReview(id){openModal(`<span class="eyebrow">YOUR EXPERIENCE</span><h2>Rate your delivery</h2><p class="muted">Help other customers choose trusted partners.</p><label class="label">Pharmacy rating</label><select id="reviewPh" class="field"><option value="5">★★★★★ 5</option><option value="4">★★★★☆ 4</option><option value="3">★★★☆☆ 3</option><option value="2">★★☆☆☆ 2</option><option value="1">★☆☆☆☆ 1</option></select><label class="label">Rider rating</label><select id="reviewRd" class="field"><option value="5">★★★★★ 5</option><option value="4">★★★★☆ 4</option><option value="3">★★★☆☆ 3</option><option value="2">★★☆☆☆ 2</option><option value="1">★☆☆☆☆ 1</option></select><label class="label">Comment</label><textarea id="reviewComment" class="field" rows="4" placeholder="How was your experience?"></textarea><button class="btn primary wide top-gap" onclick="submitReview('${id}')">Submit review</button>`)}
async function submitReview(id){try{await api('/reviews',{method:'POST',body:{orderId:id,pharmacyRating:Number($('reviewPh').value),riderRating:Number($('reviewRd').value),comment:$('reviewComment').value}});closeModal();toast('Thanks for your review!');dashboard('orders')}catch(e){toast(e.message)}}
async function payOrder(id){openModal(`<span class="eyebrow">PAYMENT</span><h2>Choose payment method</h2><p class="muted">Pay by cash on delivery or continue to the secure SSLCommerz gateway.</p><button class="btn primary wide" onclick="completePayment('${id}','COD')">Cash on Delivery</button><button class="btn wide top-gap" onclick="startOnlinePayment('${id}')">Pay online · SSLCommerz</button>`)}
async function startOnlinePayment(id){try{const result=await api('/payments/'+encodeURIComponent(id)+'/sslcommerz/initiate',{method:'POST',body:{}});if(!result.gatewayUrl)throw Error('Payment gateway did not return a checkout URL');location.href=result.gatewayUrl}catch(e){toast(e.message||'Could not start online payment')}}
async function completePayment(id,method){try{await api('/payments/'+id+'/pay',{method:'POST',body:{method}});closeModal();toast('Payment successful');dashboard('orders')}catch(e){toast(e.message)}}
async function invoice(id){if(!token)return;const r=await fetch(API+'/invoices/'+id,{headers:{Authorization:'Bearer '+token}});if(!r.ok){toast('Invoice unavailable');return}const html=await r.text();const w=window.open('','_blank');if(w){w.document.write(html);w.document.close()}else toast('Please allow pop-ups for invoice')}
async function notifications(){try{const ns=await api('/notifications');openModal(`<div class="modal-head"><span class="eyebrow">NOTIFICATIONS</span><h2>Updates</h2><button class="btn small" onclick="readAllNotifications()">Mark all as read</button></div><div class="notification-list">${ns.length?ns.map(n=>`<article class="notice ${n.read?'':'unread'}"><div class="notice-head"><span class="notice-dot ${n.read?'read':''}"></span><b>${esc(n.title)}</b>${!n.read?'<span class="unread-pill">UNREAD</span>':''}</div><p>${esc(n.message)}</p><small>${n.createdAt?new Date(n.createdAt).toLocaleString():''}</small>${!n.read?`<button class="btn small" onclick="readNotification('${n.id}')">Mark read</button>`:''}</article>`).join(''):'<div class="empty">You are all caught up.</div>'}</div>`)}catch(e){toast(e.message)}}
async function readNotification(id){try{await api('/notifications/'+id+'/read',{method:'PATCH'});notifications()}catch(e){toast(e.message)}}
async function readAllNotifications(){try{await api('/notifications/read-all',{method:'PATCH'});notifications();toast('All notifications marked as read')}catch(e){toast(e.message)}}
function renderCurrent(){if(location.pathname.endsWith('/pharmacy.html'))renderPharmacyPage();else if(location.hash==='#dashboard'&&me)renderDashboard();else home()}
async function refreshNotificationBadge(){if(!token)return;try{const r=await api('/notifications/unread-count');const b=$('notifBadge');if(b){const n=Number(r.count||0);b.textContent=n>99?'99+':n;b.hidden=n===0}}catch{}}
refreshNotificationBadge();setInterval(refreshNotificationBadge,15000);
window.addEventListener('hashchange',renderCurrent);window.addEventListener('beforeunload',()=>{if(riderWatch!==null&&navigator.geolocation)navigator.geolocation.clearWatch(riderWatch)});renderCurrent();


// Optional external integrations are enabled only when server-side credentials are configured.
window.googleClientId = window.googleClientId || '';
async function loadIntegrationConfig(){try{const c=await api('/integrations/config');window.googleClientId=c.googleClientId||'';return c;}catch(e){return {googleClientId:''};}}
function setupGoogleSignIn(){
  const host=$('googleSignIn'); if(!host)return;
  host.innerHTML='<button type="button" class="google-fallback" onclick="startGoogleSignIn()"><span class="google-g-mark">G</span><span>Continue with Google</span></button><p class="google-hint" id="googleSignInHint" hidden></p>';
  loadIntegrationConfig().then(()=>{
    if(!$('googleSignIn'))return;
    if(!window.googleClientId){const hint=$('googleSignInHint');if(hint){hint.hidden=false;hint.textContent='Google sign-in needs GOOGLE_CLIENT_ID configured in the backend environment.';}return;}
    const render=()=>{const current=$('googleSignIn');if(!window.google?.accounts?.id||!current)return;current.innerHTML='';google.accounts.id.initialize({client_id:window.googleClientId,callback:googleCredentialCallback,auto_select:false});google.accounts.id.renderButton(current,{theme:'outline',size:'large',shape:'pill',text:'continue_with',width:320});};
    if(window.google?.accounts?.id)render();else{let script=document.querySelector('script[data-google-identity]');if(!script){script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.defer=true;script.dataset.googleIdentity='1';script.onload=render;script.onerror=()=>{const hint=$('googleSignInHint');if(hint){hint.hidden=false;hint.textContent='Google sign-in library could not load. Check your internet connection.';}};document.head.appendChild(script)}else script.addEventListener('load',render,{once:true});}
  });
}
async function startGoogleSignIn(){if(!window.googleClientId){await loadIntegrationConfig();}if(!window.googleClientId){toast('Google login is not configured yet. Add GOOGLE_CLIENT_ID and restart MediPanda.');return;}if(!window.google?.accounts?.id){setupGoogleSignIn();toast('Loading Google sign-in. Please try again in a moment.');return;}google.accounts.id.prompt();}
async function googleCredentialCallback(response){try{const session=await api('/integrations/google-login',{method:'POST',body:{credential:response.credential}});setSession(session);closeModal();toast('Signed in with Google');dashboard()}catch(e){toast(e.message||'Google sign-in failed')}}
loadIntegrationConfig();

// Push notifications (FCM): ask once, then register this browser's token with the backend.
async function enablePush(){try{if(!token||!('serviceWorker' in navigator)||!('Notification' in window))return;const c=await fetch(API+'/integrations/config').then(r=>r.json());if(!c.pushEnabled)return;if(Notification.permission==='denied')return;if(Notification.permission==='default'&&await Notification.requestPermission()!=='granted')return;if(!window.firebase){await Promise.all(['app','messaging'].map(n=>new Promise((ok,no)=>{const x=document.createElement('script');x.src=`https://www.gstatic.com/firebasejs/10.12.2/firebase-${n}-compat.js`;x.onload=ok;x.onerror=no;document.head.appendChild(x)})))}
if(!firebase.apps.length)firebase.initializeApp(c.firebase);const reg=await navigator.serviceWorker.register('/firebase-messaging-sw.js?cfg='+encodeURIComponent(btoa(JSON.stringify(c.firebase))));const t=await firebase.messaging().getToken({vapidKey:c.vapidKey,serviceWorkerRegistration:reg});if(t&&localStorage.getItem('mp_push')!==t){await api('/notifications/device-token',{method:'POST',body:{token:t}});localStorage.setItem('mp_push',t)}firebase.messaging().onMessage(m=>toast((m.notification?.title||'')+': '+(m.notification?.body||'')))}catch(e){}}
if(token)setTimeout(enablePush,2500);
